import logging
from abc import ABCMeta, abstractmethod

from ute_ue.config import loggers as ta_ue_logging

from taf.ue.android.data_transfer.utils.tcp_port_finder import DEFAULT_PORT_MAX, DEFAULT_PORT_MIN, DEFAULT_PORT_SEARCH_ATTEMPTS, FreeTcpPortFinder


class AbstractIperfEndpoint(metaclass=ABCMeta):

    NETSTAT_OCCUPIED_PORTS_CMD = 'netstat -an'

    def __init__(self, endpoint_access, dt_name, dt_config):
        raw_logger = logging.getLogger('ute_ue')
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'DATATRANSFER'})

        self.endpoint_access = endpoint_access
        self.dt_name = dt_name
        self.dt_config = dt_config
        self._iperf_start_time = None
        self._iperf_stop_time = None

    @abstractmethod
    def list_occupied_ports_on_device(self):
        """Run `netstat_cmd` on device and return output"""
        raise NotImplementedError

    @abstractmethod
    def get_ip(self):
        """Get device ip address"""
        raise NotImplementedError

    @abstractmethod
    def get_bind_ip(self):
        """Return Ip for iperf -B option"""
        raise NotImplementedError

    @abstractmethod
    def get_iperf_path(self):
        """Return iperf binary path and name: /path/to/iperf/binary_name"""
        raise NotImplementedError

    @abstractmethod
    def start_iperf(self, cmd):
        """Start iperf command on app server or UE"""
        raise NotImplementedError

    @abstractmethod
    def kill_iperf(self):
        """Stop or kill iperf process on app server or UE"""
        raise NotImplementedError

    @abstractmethod
    def is_iperf_running(self):
        raise NotImplementedError

    @abstractmethod
    def read_iperf_output(self):
        raise NotImplementedError

    def get_iperf_connection_ip(self):
        """
        Returns ip of iperf server to which iperf client should connect to
        Returns binding interface ip if set or default iperf server ip
        """
        return self.get_bind_ip() or self.get_ip()

    def find_free_port(self, min_port=DEFAULT_PORT_MIN, max_port=DEFAULT_PORT_MAX,
                       attempts=DEFAULT_PORT_SEARCH_ATTEMPTS):
        """Get random free port on device in range (min_port:max_port]"""
        self.logger.debug(f"{repr(self)}: searching random free port based on `{self.NETSTAT_OCCUPIED_PORTS_CMD}` "
                          "cmd output.")
        netstat_output = self.list_occupied_ports_on_device()
        free_port = FreeTcpPortFinder.find_random_free_port(
            port_validator=lambda port: FreeTcpPortFinder.is_port_free_in_netstat(netstat_output, port),
            min_port=min_port, max_port=max_port, attempts=attempts)
        self.logger.debug(f'{repr(self)}: chosen port {free_port}.')
        return free_port

    def is_port_free(self, port):
        """Check if port is free on device"""
        self.logger.debug(f"{repr(self)}: checking if port {port} is free based on `{self.NETSTAT_OCCUPIED_PORTS_CMD}` "
                          "cmd output.")
        netstat_output = self.list_occupied_ports_on_device()
        is_port_free = FreeTcpPortFinder.is_port_free_in_netstat(netstat_output, port)
        self.logger.debug(f"{repr(self)}: port {port} is {self.port_status(is_port_free)}")
        return is_port_free

    @staticmethod
    def port_status(status):
        return 'free' if status is True else "already in use"

    @staticmethod
    def get_corrected_iperf_path(iperf_path, binary_name):
        """Verifies if iperf_path from yaml cfg or robot kwargs is fullpath to binary and corrects it if needed"""
        win_os_sep = "\\"
        lin_os_sep = "/"
        if iperf_path.endswith((binary_name, f"{binary_name}.exe")):
            return iperf_path
        if iperf_path.endswith((lin_os_sep, win_os_sep)):
            return iperf_path + binary_name
        if lin_os_sep in iperf_path:
            return iperf_path + lin_os_sep + binary_name
        if win_os_sep in iperf_path:
            return iperf_path + win_os_sep + binary_name

    @property
    def iperf_start_time(self):
        """Singleton property to indicate iperf start time"""
        return self._iperf_start_time

    @iperf_start_time.setter
    def iperf_start_time(self, value):
        """Iperf start time setter"""
        if not self._iperf_start_time:
            self._iperf_start_time = value

    @property
    def iperf_stop_time(self):
        """Singleton property to indicate iperf stop time"""
        return self._iperf_stop_time

    @iperf_stop_time.setter
    def iperf_stop_time(self, value):
        """Iperf stop time setter"""
        if not self._iperf_stop_time:
            self._iperf_stop_time = value

    def __repr__(self):
        return self.__class__.__name__
